#!/usr/bin/env python3
"""voynann-video-editor · render-video.py

Renders edit.json into a real MP4: FFmpeg cuts the footage and voice, sound.py builds SFX + music + the
loudness-normalised mix, Remotion composites footage, captions and motion graphics frame by frame.

  python3 render-video.py work/edit.json --stills 0.3,2.1,5.4        # check frames first (PNG + contact sheet)
  python3 render-video.py work/edit.json --range 0-6 --out out/preview.mp4
  python3 render-video.py work/edit.json --out out/final.mp4 --budget 170

Resumable: Remotion renders in chunks; if the --budget (seconds) runs out the script exits with code 2 and
prints NOT FINISHED. Run the SAME command again and it continues where it stopped. Exit 0 = MP4 written.
Changing edit.json invalidates only what changed (cut footage, audio mix, frame chunks are hashed separately).
"""
import argparse, hashlib, json, os, shutil, subprocess, sys, time
from pathlib import Path

HERE = Path(__file__).resolve().parent
SKILL = HERE.parent
sys.path.insert(0, str(HERE))


def sh(cmd, **kw):
    r = subprocess.run(cmd, capture_output=True, text=True, **kw)
    if r.returncode != 0:
        raise RuntimeError(f"command failed: {' '.join(map(str, cmd[:6]))} ...\n{r.stderr[-1500:]}")
    return r


def h(obj):
    return hashlib.sha1(json.dumps(obj, sort_keys=True).encode()).hexdigest()[:12]


def log(*a):
    print("[render]", *a, flush=True)


def find_chrome():
    spec = __import__("importlib.util").util.spec_from_file_location("im", HERE / "inspect-media.py")
    mod = __import__("importlib.util").util.module_from_spec(spec); spec.loader.exec_module(mod)
    return mod.find_chrome()


# --------------------------------------------------------------------------------------------- project setup
def setup_project(work, install=True):
    proj = work / "remotion"
    tpl = SKILL / "assets" / "remotion"
    proj.mkdir(parents=True, exist_ok=True)
    for name in ("package.json", "render.mjs"):
        shutil.copy2(tpl / name, proj / name)
    if (proj / "src").exists():
        shutil.rmtree(proj / "src")
    shutil.copytree(tpl / "src", proj / "src")
    pub = proj / "public"; (pub / "fonts").mkdir(parents=True, exist_ok=True); (pub / "fx").mkdir(parents=True, exist_ok=True)
    for f in (SKILL / "assets" / "fonts").iterdir():
        if f.suffix in (".ttf", ".woff2", ".otf") and not (pub / "fonts" / f.name).exists():
            shutil.copy2(f, pub / "fonts" / f.name)
    for f in (SKILL / "assets" / "fx").iterdir():
        if not (pub / "fx" / f.name).exists():
            shutil.copy2(f, pub / "fx" / f.name)
    if install and not (proj / "node_modules" / "@remotion" / "renderer").exists():
        log("installing Remotion (one time, ~30 s) ...")
        sh(["npm", "install", "--no-audit", "--no-fund", "--loglevel=error"], cwd=proj)
    return proj


def install_custom(E, proj):
    """Creative mode: copy the per-video components listed in edit.json["custom"] into the project and register their
    named exports as overlay types (src/components/custom/index.js). The shipped template registers nothing."""
    cdir = proj / "src" / "components" / "custom"
    cdir.mkdir(parents=True, exist_ok=True)
    lines, names = [], []
    for k, c in enumerate(E.get("custom") or []):
        src = Path(c["file"])
        if not src.exists():
            sys.exit(f"custom component not found: {src} (re-run plan-edit.py)")
        dst = cdir / f"{c['name']}.jsx"
        shutil.copy2(src, dst)
        lines.append(f"import * as c{k} from './{dst.name}';")
        names.append(f"...c{k}")
    body = "\n".join(lines) + ("\n" if lines else "") + f"export const CUSTOM = {{{', '.join(names)}}};\n"
    (cdir / "index.js").write_text("// generated by render-video.py from creative.json custom_components\n" + body)
    if lines:
        log(f"creative mode: {len(lines)} custom component file(s) -> {', '.join(c['name'] for c in E['custom'])}")


# --------------------------------------------------------------------------------------------- footage + audio
def cut_media(E, work, pub):
    key = h({"segs": E["segments"], "src": E["source"]["video"], "fps": E["fps"]})
    vid, voice = pub / "cut.mp4", work / "voice_cut.wav"
    stamp = work / ".cut.hash"
    if vid.exists() and voice.exists() and stamp.exists() and stamp.read_text() == key:
        return vid, voice
    fps = E["fps"]
    # Video: one select pass over the source (frame-exact on the normalised CFR file). The old trim+concat graph
    # split the stream once per segment and buffered every frame for the branches still waiting, which runs out of
    # memory on long edits with many cuts. Audio keeps per-segment trims (cheap) for the 8 ms de-click fades.
    parts_a, fil, sel = [], [], []
    for i, s in enumerate(E["segments"]):
        a, b = s["src"]
        f0, f1 = int(round(a * fps)), int(round(b * fps))
        sel.append(f"between(n,{f0},{f1 - 1})")
        fade = 0.008
        fil.append(f"[1:a]atrim=start={f0 / fps:.5f}:end={f1 / fps:.5f},asetpts=PTS-STARTPTS,"
                   f"afade=t=in:st=0:d={fade},afade=t=out:st={(f1 - f0) / fps - fade:.5f}:d={fade}[a{i}]")
        parts_a.append(f"[a{i}]")
    n = len(E["segments"])
    fil.insert(0, "[0:v]select='" + "+".join(sel) + "',setpts=N/FRAME_RATE/TB[vout]")
    fil.append("".join(parts_a) + f"concat=n={n}:v=0:a=1[aout]")
    graph = work / "cut_graph.txt"; graph.write_text(";\n".join(fil))
    log(f"cutting footage into {n} segments ...")
    sh(["ffmpeg", "-v", "error", "-y", "-i", E["source"]["video"], "-i", E["source"]["voice"], "-filter_complex_script", str(graph),
        "-map", "[vout]", "-c:v", "libx264", "-preset", "veryfast", "-crf", "15", "-g", "15", "-bf", "0", "-pix_fmt", "yuv420p",
        "-r", str(fps), "-movflags", "+faststart", str(vid),
        "-map", "[aout]", "-c:a", "pcm_s16le", "-ar", "48000", str(voice)])
    stamp.write_text(key)
    return vid, voice


def extra_assets(E, pub):
    """User-supplied b-roll (photos / clips) referenced by BRoll overlays."""
    for a_ in E.get("assets", []):
        dst = pub / a_["file"]
        if dst.exists() and dst.stat().st_mtime >= Path(a_["src"]).stat().st_mtime: continue
        dst.parent.mkdir(parents=True, exist_ok=True)
        src = Path(a_["src"])
        if src.suffix.lower() in (".mov", ".mkv", ".webm", ".m4v", ".mp4"):
            # normalise clips to H.264 60 fps CFR so the browser decoder seeks frame-accurately
            sh(["ffmpeg", "-v", "error", "-y", "-i", str(src), "-an", "-vf", "fps=60,scale='min(1080,iw)':-2", "-c:v", "libx264", "-preset", "veryfast",
                "-crf", "18", "-pix_fmt", "yuv420p", "-g", "15", "-movflags", "+faststart", str(dst)])
        else:
            from PIL import Image, ImageOps
            if src.suffix.lower() in (".jpg", ".jpeg", ".png", ".webp"):
                im = ImageOps.exif_transpose(Image.open(src)).convert("RGB")  # phone photos carry EXIF rotation
                im.thumbnail((2160, 2160)); im.save(dst, quality=92)
            else:
                shutil.copy2(src, dst)


# --------------------------------------------------------------------------------------------- background removal (person matte)
MATTE_URL = "https://github.com/danielgatis/rembg/releases/download/v0.0.0/silueta.onnx"


def matte_model():
    """Local person-segmentation model: the U2-Net based "silueta" build published by the rembg project (~43 MB, not bundled).
    Downloaded once to the shared model cache; returns None when the network refuses it."""
    d = Path(os.environ.get("VY_MODELS", Path.home() / ".cache" / "voynann-models")); d.mkdir(parents=True, exist_ok=True)
    f = d / "silueta.onnx"
    if f.exists() and f.stat().st_size > 1e7: return f
    log("downloading the background-removal model (one time, ~43 MB) ...")
    try:
        import urllib.request
        tmp = f.with_suffix(".part")
        with urllib.request.urlopen(MATTE_URL, timeout=120) as r, open(tmp, "wb") as out:
            shutil.copyfileobj(r, out)
        tmp.rename(f)
        return f
    except Exception as e:  # noqa: BLE001
        log(f"WARNING: background-removal model unavailable ({e}); text stays in front of the speaker. Tell the user.")
        return None


def compute_matte(E, work, pub, t0, budget, only_times=None):
    """Person masks (RGBA PNG, white + alpha) on the CUT timeline at matte.fps, only inside the planned ranges
    (text behind the speaker, Cutout). Cached and resumable; stills only compute the frames they show."""
    M = E.get("matte") or {}
    if not M.get("ranges"): return
    import math
    fps_m = M.get("fps", 30)
    key = h({"segs": E["segments"], "src": E["source"]["video"], "fps": fps_m, "v": 4})
    d = pub / "matte" / key; d.mkdir(parents=True, exist_ok=True)
    ks = sorted({k for a_, b_ in M["ranges"] for k in range(int(math.ceil(a_ * fps_m)), int(math.floor(b_ * fps_m)) + 1)})
    if only_times is not None:
        ks = sorted({k for t in only_times for k in ks if abs(k / fps_m - t) <= 1.01 / fps_m})
    todo = [k for k in ks if not (d / f"m_{k:05d}.png").exists()]
    E["matte"]["dir"] = f"matte/{key}"
    if not todo: return
    model = matte_model()
    if not model:
        E["matte"] = None; return
    import cv2, numpy as np, onnxruntime as ort
    sess = ort.InferenceSession(str(model), providers=["CPUExecutionProvider"])
    iname = sess.get_inputs()[0].name
    cap = cv2.VideoCapture(str(pub / "cut.mp4"))
    vfps = cap.get(cv2.CAP_PROP_FPS) or E["fps"]
    mean, std = np.array([0.485, 0.456, 0.406], np.float32), np.array([0.229, 0.224, 0.225], np.float32)
    faces = E.get("faces") or [[0.0, 0.5, 0.42, 0.2]]
    def face_at(t):  # tracked face centre on the cut timeline (edited seconds) -> (cx, cy) fractions
        f = min(faces, key=lambda r: abs(r[0] - t)); return f[1], f[2]
    log(f"background removal: {len(todo)} frame(s) (~{len(todo) * 1.0:.0f} s) ...")
    prev, prev_k, pos = None, None, -1
    for k in todo:
        if time.time() - t0 > budget - 20:
            print(f"NOT FINISHED (time budget, background removal {todo.index(k)}/{len(todo)}). Run the same command again to continue.")
            sys.exit(2)
        idx = int(round(k / fps_m * vfps))
        if idx != pos + 1: cap.set(cv2.CAP_PROP_POS_FRAMES, idx)
        ok, fr = cap.read(); pos = idx
        if not ok: continue
        x = cv2.resize(cv2.cvtColor(fr, cv2.COLOR_BGR2RGB), (320, 320)).astype(np.float32) / 255.0
        x = ((x - mean) / std).transpose(2, 0, 1)[None].astype(np.float32)
        m = sess.run(None, {iname: x})[0][0, 0]
        m = (m - m.min()) / (m.max() - m.min() + 1e-6)
        m = cv2.resize(m, (540, 960), interpolation=cv2.INTER_LINEAR)
        if prev is not None and prev_k == k - 1: m = 0.65 * m + 0.35 * prev  # temporal smoothing against edge flicker
        prev, prev_k = m, k
        # keep only the speaker: open the mask to cut thin bridges (door frames, wall edges the model half-detects),
        # keep the blob under the tracked face plus big blobs touching the bottom edge (torso, hands), then a soft edge
        hard = (m > 0.55).astype(np.uint8)
        hard = cv2.morphologyEx(hard, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (41, 41)))
        n, lab, stats, _ = cv2.connectedComponentsWithStats(hard, 8)
        keep = np.zeros_like(hard)
        if n > 1:
            fc = face_at(k / fps_m)
            fx_, fy_ = int(np.clip(fc[0] * 540, 0, 539)), int(np.clip(fc[1] * 960, 0, 959))
            main = lab[fy_, fx_]
            if main == 0:
                main = 1 + int(np.argmax(stats[1:, cv2.CC_STAT_AREA]))
            amain = stats[main, cv2.CC_STAT_AREA]
            for j in range(1, n):
                touches_bottom = stats[j, cv2.CC_STAT_TOP] + stats[j, cv2.CC_STAT_HEIGHT] >= 955
                if j == main or (touches_bottom and stats[j, cv2.CC_STAT_AREA] >= 0.2 * amain): keep[lab == j] = 1
        keep = cv2.dilate(keep, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (45, 45)))
        a = np.clip((m - 0.32) / 0.36, 0, 1) * keep
        a = cv2.GaussianBlur(a, (5, 5), 0)
        rgba = np.dstack([np.full_like(a, 255), np.full_like(a, 255), np.full_like(a, 255), a * 255]).astype(np.uint8)
        cv2.imwrite(str(d / f"m_{k:05d}.png"), rgba)


def thumbs(E, pub):
    for th in E.get("thumbs", []):
        out = pub / th["file"]
        if out.exists(): continue
        out.parent.mkdir(parents=True, exist_ok=True)
        sh(["ffmpeg", "-v", "error", "-y", "-ss", f"{th['src_time']:.3f}", "-i", E["source"]["video"], "-frames:v", "1",
            "-vf", "scale=360:-2", "-q:v", "3", str(out)])


def audio_mix(E, work, voice):
    import sound
    M = E["music"]
    key = h({"segs": E["segments"], "sfx": E["sfx"], "music": M, "dur": E["duration"], "v": 5})
    out = work / "mix.wav"; stamp = work / ".mix.hash"
    if out.exists() and stamp.exists() and stamp.read_text() == key:
        return out
    log("building sound: voice clean-up, SFX, music bed, loudness ...")
    lvl = E["settings"].get("sound_effects", "medium")
    inten = {"off": 0, "subtle": 0.8, "medium": 1.0, "energetic": 1.15}.get(lvl, 1.0)
    info = sound.mix(voice, E["duration"], E["sfx"] if lvl != "off" else [], out, style=M["style"], music=M["enabled"],
                     music_db=M["db"], sfx_db=M["sfx_db"], sfx_intensity=inten, music_hit_at=M.get("hit_at"),
                     music_break_at=M.get("break_at"), tmp=work / "tmp_audio", music_file=M.get("file"))
    (work / "mix_info.json").write_text(json.dumps(info, indent=1))
    stamp.write_text(key)
    return out


# --------------------------------------------------------------------------------------------- FFmpeg fallback engine
# Used when no Chromium can run (or with --engine ffmpeg). Keeps: cuts, face-anchored camera zooms/punch-ins,
# word-highlight captions (ASS/libass), the full sound mix. Drops: layouts (cards/split), overlays/motion graphics.
def ass_color(hexcol, alpha=0):
    h_ = hexcol.lstrip("#")
    r, g, b = h_[0:2], h_[2:4], h_[4:6]
    return f"&H{alpha:02X}{b}{g}{r}".upper()


def ass_time(t):
    t = max(0.0, t)
    return f"{int(t // 3600)}:{int(t % 3600 // 60):02d}:{t % 60:05.2f}"


def write_ass(E, path):
    S, C = E["style"]["captions"], E["style"]["colors"]
    W, H = E["width"], E["height"]
    look = S["variant"]
    fam = E["style"]["fonts"]["head" if look in ("box", "stroke") else ("body" if look in ("clean", "glass") else "ui")]
    # libass needs TTF/OTF: the web fonts (woff2) used by the Remotion engine map to the bundled TTF closest in feel
    font = {"PlusJakartaSans": "Plus Jakarta Sans ExtraBold", "Montserrat": "Plus Jakarta Sans ExtraBold", "TikTokSans": "Plus Jakarta Sans ExtraBold", "Manrope": "Plus Jakarta Sans ExtraBold", "BricolageGrotesque": "Plus Jakarta Sans ExtraBold",
            "PlusJakarta": "Plus Jakarta Sans ExtraBold", "Unbounded": "Plus Jakarta Sans ExtraBold",
            "DMSans": "DM Sans", "Poppins": "DM Sans", "SpaceGrotesk": "Space Grotesk", "Geist": "Space Grotesk", "GeistMono": "Space Grotesk",
            "InterTight": "DM Sans", "Outfit": "Plus Jakarta Sans ExtraBold", "Archivo": "Plus Jakarta Sans ExtraBold"}.get(fam, "DM Sans")
    bold = 0 if "ExtraBold" in font else 1
    if look == "box":
        prim, outl, back, bs, ol, sh = ass_color(C["ink"]), ass_color(S.get("box", C["paper"])), ass_color(S.get("box", C["paper"])), 3, int(S["size"] * 0.28), 0
        active = ass_color(C["accent2"])
    elif look == "stroke":
        prim, outl, back, bs, ol, sh = ass_color(S.get("text", "#FFFFFF")), ass_color(S.get("stroke", "#000000")), ass_color("#000000", 0x80), 1, max(4, int(S["size"] * 0.12)), 2
        active = ass_color(S.get("active", C["accent"]))
    elif look in ("terminal", "glass"):
        prim, outl, back, bs, ol, sh = ass_color(C["paper"]), ass_color(C["ink"], 0x20), ass_color(C["ink"], 0x20), 3, int(S["size"] * 0.3), 0
        active = ass_color(C["accent"])
    else:  # clean / type: white text, soft outline + shadow
        prim, outl, back, bs, ol, sh = ass_color(C["paper"]), ass_color("#000000", 0x60), ass_color("#000000", 0x80), 1, 2, 3
        active = ass_color(C["accent"])
    y = E["captions"]["y"]
    head = (f"[Script Info]\nScriptType: v4.00+\nPlayResX: {W}\nPlayResY: {H}\nWrapStyle: 0\nScaledBorderAndShadow: yes\n\n"
            "[V4+ Styles]\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, "
            "StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\n"
            f"Style: Cap,{font},{round(S['size'] * 1.42)},{prim},{prim},{outl},{back},{bold},0,0,0,100,100,0,0,{bs},{ol},{sh},2,80,80,{H - y + ol},1\n\n"
            "[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n")
    zones = E["captions"].get("zones", [])
    def zone(t):
        z = None
        for zz in zones:
            if zz["from"] <= t < zz["to"]: z = zz
        return z or {}
    lines = []
    k_size = 1.42  # libass sizes are line heights; scale so glyphs match the CSS pixel sizes used by the Remotion engine
    for pg in E["captions"]["pages"]:
        z = zone(pg["start"])
        # zone position/size/hidden overrides belong to layouts (cards, end cards) the fallback cannot draw: ignore them
        mv = H - y + ol
        size = round((S["hookSize"] if z.get("variant") == "hook" else S["size"]) * k_size)
        words = pg["words"]
        bounds = [pg["start"]] + [w["start"] for w in words[1:]] + [pg["end"]]
        for k in range(len(words)):
            a, b = (pg["start"] if k == 0 else words[k]["start"]), bounds[k + 1]
            if b - a < 0.01: continue
            txt = []
            for j, w in enumerate(words):
                t_ = w["text"].upper() if S.get("case") == "upper" else w["text"]
                t_ = t_.replace("{", "(").replace("}", ")")
                if j == k: txt.append(f"{{\\c{active}}}{t_}{{\\c{prim}}}")
                else: txt.append(t_)
            pop = "{\\fscx86\\fscy86\\t(0,110,\\fscx100\\fscy100)}" if k == 0 else ""
            lines.append(f"Dialogue: 0,{ass_time(a)},{ass_time(b)},Cap,,0,0,{mv},,{pop}{{\\fs{size}}}" + " ".join(txt))
    Path(path).write_text(head + "\n".join(lines) + "\n", encoding="utf-8")


def camera_expr(E):
    keys = E.get("camera") or [{"t": 0, "s": 1.0, "fx": 0.5, "fy": 0.45}]
    def piece(field, default):
        expr = f"{keys[0].get(field, default)}"
        prev = keys[0].get(field, default)
        for k in keys[1:]:
            v = k.get(field, prev)
            d = max(0.001, k.get("dur", 0.4)) if k.get("ease") != "cut" else 0.001
            p = f"clip((t-{k['t']:.3f})/{d:.3f},0,1)"
            e = f"({p}*{p}*(3-2*{p}))"
            expr = f"if(lt(t,{k['t']:.3f}),{expr},{prev}+({v}-{prev})*{e})"
            prev = v
        return expr
    z = piece("s", 1.0)
    jz = "1"
    for t, k in E.get("jumpZoom", []):
        jz = f"if(gte(t,{t:.3f}),{k},{jz})"
    # rhythm pushes (slow dolly-ins added by the planner)
    pk = E.get("camPush") or []
    push = "1"
    if pk:
        push, prev = f"{pk[0].get('k', 1)}", pk[0].get("k", 1)
        for k in pk[1:]:
            d = max(0.001, k.get("dur", 0.4)) if k.get("ease") != "cut" else 0.001
            p_ = f"clip((t-{k['t']:.3f})/{d:.3f},0,1)"
            push = f"if(lt(t,{k['t']:.3f}),{push},{prev}+({k['k']}-{prev})*({p_}*{p_}*(3-2*{p_})))"
            prev = k["k"]
    return f"({z})*({jz})*({push})", piece("fx", 0.5), piece("fy", 0.45)


def render_ffmpeg(E, work, pub, mix, out, rng=None):
    W, H, fps = E["width"], E["height"], E["fps"]
    vw, vh = E["footage"]["width"], E["footage"]["height"]
    c = max(W / vw, H / vh)
    faces = E.get("faces") or [[0, 0.5, 0.42, 0.2]]
    fcx = sorted(f[1] for f in faces)[len(faces) // 2]; fcy = sorted(f[2] for f in faces)[len(faces) // 2]
    Z, FX, FY = camera_expr(E)
    ass = work / "captions.ass"; write_ass(E, ass)
    fontsdir = SKILL / "assets" / "fonts"
    G = E["style"]["grade"]
    graph = (f"[0:v]scale=w='trunc({vw * c:.2f}*({Z})/2)*2':h='trunc({vh * c:.2f}*({Z})/2)*2':eval=frame:flags=bicubic,"
             f"crop={W}:{H}:x='clip({fcx:.4f}*iw-({FX})*{W},0,iw-{W})':y='clip({fcy:.4f}*ih-({FY})*{H},0,ih-{H})',"
             f"eq=saturation={G['sat']}:contrast={G['con']}:brightness={(G['bri'] - 1) * 0.5:.3f},"
             f"tpad=stop_mode=clone:stop_duration={max(0.0, E['duration'] - E['footage']['duration']) + 0.1:.2f},"
             f"subtitles='{ass}':fontsdir='{fontsdir}',format=yuv420p[v]")
    gfile = work / "ffmpeg_graph.txt"; gfile.write_text(graph)
    ss, end = (rng if rng else (0.0, E["duration"]))
    # output-side seek keeps the filter clock (t) on the edited timeline, so camera keys and captions stay in sync
    sh(["ffmpeg", "-v", "error", "-y", "-i", str(pub / "cut.mp4"), "-i", str(mix), "-filter_complex_script", str(gfile),
        "-map", "[v]", "-map", "1:a:0", "-ss", f"{ss:.3f}", "-t", f"{end - ss:.3f}", "-r", str(fps), "-c:v", "libx264", "-preset", "veryfast",
        "-crf", "18", "-c:a", "aac", "-b:a", "192k", "-movflags", "+faststart", "-color_primaries", "bt709", "-color_trc", "bt709",
        "-colorspace", "bt709", str(out)])


# --------------------------------------------------------------------------------------------- remotion calls
def node(proj, args, env, timeout=None):
    return subprocess.run(["node", "render.mjs", *args], cwd=proj, env=env, capture_output=True, text=True, timeout=timeout)


def contact_sheet(pngs, times, out, cols=4):
    from PIL import Image, ImageDraw, ImageFont
    ims = [Image.open(p).convert("RGB") for p in pngs]
    w, h_ = ims[0].size
    tw = 360; th = int(h_ * tw / w)
    rows = (len(ims) + cols - 1) // cols
    sheet = Image.new("RGB", (cols * tw + (cols + 1) * 12, rows * (th + 44) + 12), (24, 24, 24))
    d = ImageDraw.Draw(sheet)
    try:
        font = ImageFont.truetype(str(SKILL / "assets" / "fonts" / "SpaceGrotesk_700Bold.ttf"), 26)
    except Exception:  # noqa: BLE001
        font = None
    for k, (im, t) in enumerate(zip(ims, times)):
        x = 12 + (k % cols) * (tw + 12); y = 12 + (k // cols) * (th + 44)
        sheet.paste(im.resize((tw, th)), (x, y + 34))
        d.text((x, y), f"{t:.2f}s", fill=(200, 255, 46), font=font)
    sheet.save(out, quality=88)


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("edit")
    ap.add_argument("--out")
    ap.add_argument("--stills", help="comma-separated edited-time seconds")
    ap.add_argument("--range", help="render only A-B seconds (preview)")
    ap.add_argument("--budget", type=float, default=float(os.environ.get("VY_BUDGET", 170)))
    ap.add_argument("--chunk", type=int, default=60, help="frames per chunk")
    ap.add_argument("--fresh", action="store_true", help="discard cached chunks")
    ap.add_argument("--redo", help="A-B seconds: after a small revision, re-render only chunks touching this range")
    ap.add_argument("--engine", choices=["auto", "remotion", "ffmpeg"], default="auto",
                    help="remotion = full motion graphics (needs Node + Chromium); ffmpeg = fallback without browser (cuts, zooms, captions, sound only)")
    a = ap.parse_args()
    t0 = time.time()
    ep = Path(a.edit).resolve(); work = ep.parent
    E = json.loads(ep.read_text())
    if E.get("fps") != 60:
        sys.exit("Invalid edit.json fps: this skill always renders at 60 fps; regenerate with plan-edit.py")
    if E.get("durationInFrames") != int(round(E["duration"] * E["fps"])):
        sys.exit("edit.json durationInFrames does not match fps/duration; regenerate the plan")
    media_path = work / "media.json"
    if media_path.exists():
        actual = json.loads(media_path.read_text()).get("normalized", {}).get("fps")
        if actual != E["fps"]:
            sys.exit(f"Normalized source fps={actual}, edit fps={E['fps']}. Re-run inspect-media.py with --fps {E['fps']} then plan-edit.py")
    env = dict(os.environ)
    chrome = env.get("VY_BROWSER") or find_chrome()
    engine = a.engine
    if engine == "auto":
        engine = "remotion" if chrome and shutil.which("node") else "ffmpeg"
        if engine == "ffmpeg":
            log("WARNING: no Chromium/Node found -> FFmpeg fallback (cuts, zooms, captions, sound; NO motion graphics). Tell the user.")
    proj = setup_project(work, install=engine == "remotion")
    install_custom(E, proj)
    pub = proj / "public"
    _, voice = cut_media(E, work, pub)
    thumbs(E, pub)
    extra_assets(E, pub)
    if engine == "ffmpeg":
        mix = audio_mix(E, work, voice)
        if a.stills:
            times = [float(x) for x in a.stills.split(",") if x.strip()]
            full = work / "ffmpeg_full.mp4"
            render_ffmpeg(E, work, pub, mix, full)
            sd = work / "stills"; sd.mkdir(exist_ok=True)
            pngs = []
            for t in times:
                f = sd / f"still_{int(round(t * E['fps'])):05d}.png"
                sh(["ffmpeg", "-v", "error", "-y", "-ss", f"{t:.3f}", "-i", str(full), "-frames:v", "1", str(f)]); pngs.append(str(f))
            contact_sheet(pngs, times, sd / "sheet.jpg")
            log(f"{len(pngs)} stills (ffmpeg engine) -> {sd / 'sheet.jpg'}"); return
        out = Path(a.out or work / "final.mp4"); out.parent.mkdir(parents=True, exist_ok=True)
        rng = tuple(float(v) for v in a.range.split("-")) if a.range else None
        render_ffmpeg(E, work, pub, mix, out, rng)
        log(f"done (ffmpeg engine) -> {out} ({out.stat().st_size / 1e6:.1f} MB, {time.time() - t0:.0f}s)")
        print("DONE", out); return
    if chrome: env["VY_BROWSER"] = chrome
    if chrome and "chrome-headless-shell" not in chrome and "headless_shell" not in chrome:
        env.setdefault("VY_CHROME_MODE", "chrome-for-testing")
    if E.get("matte"):
        st = [float(x) for x in a.stills.split(",") if x.strip()] if a.stills else None
        compute_matte(E, work, pub, t0, a.budget, st)
    props = work / "props.json"; props.write_text(json.dumps(E))

    if a.stills:
        times = [float(x) for x in a.stills.split(",") if x.strip()]
        sd = work / "stills"; sd.mkdir(exist_ok=True)
        for f in sd.glob("still_*.png"): f.unlink()
        r = node(proj, ["stills", "--props", str(props), "--times", ",".join(map(str, times)), "--outdir", str(sd)], env)
        if r.returncode != 0:
            print(r.stderr[-3000:])
            if E.get("custom"):
                print("HINT: creative mode is on. If the error names a custom component, fix that .jsx file; if it fails twice, "
                      "remove it from custom_components and use a library overlay instead.")
            sys.exit(1)
        pngs = [l.strip() for l in r.stdout.splitlines() if l.strip().endswith(".png")]
        contact_sheet(pngs, times, sd / "sheet.jpg")
        log(f"{len(pngs)} stills -> {sd / 'sheet.jpg'} ({time.time() - t0:.0f}s)")
        return

    mix = audio_mix(E, work, voice)
    fps, N = E["fps"], E["durationInFrames"]
    f0, f1 = 0, N - 1
    tag = "full"
    if a.range:
        x, y = (float(v) for v in a.range.split("-"))
        f0, f1 = int(round(x * fps)), min(N - 1, int(round(y * fps)) - 1)
        tag = f"range_{f0}_{f1}"
    # Frame chunks depend on everything visual (not on sfx/music). A changed edit.json invalidates all chunks,
    # unless --redo A-B says which seconds changed (revision workflow): then only those chunks are re-rendered.
    src_hash = hashlib.sha1(b"".join(p.read_bytes() for p in sorted((proj / "src").rglob("*")) if p.is_file())).hexdigest()[:12]
    key = h({"E": {k: v for k, v in E.items() if k not in ("lint", "sfx", "music")}, "src": src_hash})
    cdir = work / "chunks"
    kfile = cdir / ".key"
    if a.fresh and cdir.exists(): shutil.rmtree(cdir)
    cdir.mkdir(parents=True, exist_ok=True)
    old = kfile.read_text() if kfile.exists() else None
    if old != key:
        if a.redo and old is not None:
            x, y = (float(v) for v in a.redo.split("-"))
            lo, hi = int((x - 0.5) * fps), int((y + 0.5) * fps)
            gone = 0
            for p in cdir.glob("c_*.mp4"):
                c0, c1 = int(p.stem.split("_")[1]), int(p.stem.split("_")[2])
                if c1 >= lo and c0 <= hi: p.unlink(); gone += 1
            log(f"--redo {a.redo}: re-rendering {gone} chunk(s), keeping the rest")
        else:
            for p in cdir.glob("c_*.mp4"): p.unlink()
        kfile.write_text(key)
    # chunk grid is global (aligned to multiples of --chunk) so previews and full renders share chunks
    budget_left = a.budget - (time.time() - t0)
    first_aligned = (f0 // a.chunk) * a.chunk
    r = node(proj, ["chunks", "--props", str(props), "--outdir", str(cdir), "--chunk", str(a.chunk), "--budget", str(max(20, budget_left)),
                    "--from", str(first_aligned), "--to", str(min(N - 1, ((f1 // a.chunk) + 1) * a.chunk - 1))], env)
    sys.stderr.write(r.stderr[-2000:] if r.returncode not in (0, 2) else "")
    for line in r.stderr.splitlines():
        if line.startswith("[remotion]"): log(line[11:])
    if r.returncode == 2:
        print(f"NOT FINISHED (time budget). Run the same command again to continue. ({time.time() - t0:.0f}s)")
        sys.exit(2)
    if r.returncode != 0:
        print(r.stdout[-1000:])
        if E.get("custom"):
            print("HINT: creative mode is on - check the custom components with --stills first.")
        sys.exit(1)
    # pick a gap-free, non-overlapping run of chunks covering [f0, f1] (previews may leave shorter chunks behind)
    avail = {}
    for p in cdir.glob("c_*.mp4"):
        if p.name.endswith(".part.mp4"): continue
        c0, c1 = int(p.stem.split("_")[1]), int(p.stem.split("_")[2])
        if c1 > avail.get(c0, (-1, None))[0]: avail[c0] = (c1, p)
    chunks, nxt = [], first_aligned
    while nxt <= f1:
        if nxt not in avail:
            print(f"missing frames from {nxt}; run again"); sys.exit(2)
        c1, p = avail[nxt]; chunks.append(p); nxt = c1 + 1
    lst = work / f"concat_{tag}.txt"
    lst.write_text("".join(f"file '{p.resolve()}'\n" for p in chunks))
    vtmp = work / f"video_{tag}.mp4"
    sh(["ffmpeg", "-v", "error", "-y", "-f", "concat", "-safe", "0", "-i", str(lst), "-c", "copy", str(vtmp)])
    out = Path(a.out or work / ("final.mp4" if not a.range else f"preview_{f0}_{f1}.mp4"))
    out.parent.mkdir(parents=True, exist_ok=True)
    first_chunk = int(chunks[0].stem.split("_")[1])
    ss = (f0 - first_chunk) / fps
    dur = (f1 - f0 + 1) / fps
    sh(["ffmpeg", "-v", "error", "-y", "-ss", f"{ss:.4f}", "-i", str(vtmp), "-ss", f"{f0 / fps:.4f}", "-i", str(mix),
        "-t", f"{dur:.4f}", "-frames:v", str(f1 - f0 + 1), "-map", "0:v:0", "-map", "1:a:0",
        *(["-c:v", "copy"] if ss == 0 else ["-c:v", "libx264", "-preset", "veryfast", "-crf", "17", "-pix_fmt", "yuv420p"]),
        "-c:a", "aac", "-b:a", "192k", "-ar", "48000", "-movflags", "+faststart",
        "-color_primaries", "bt709", "-color_trc", "bt709", "-colorspace", "bt709", str(out)])
    size = out.stat().st_size / 1e6
    log(f"done -> {out} ({size:.1f} MB, {dur:.2f}s, {time.time() - t0:.0f}s)")
    print("DONE", out)


if __name__ == "__main__":
    main()
